        Chapter(
            "tailoring",
            "⚙️ Tailoring & Development Approaches",
            "What Is Tailoring?",
            "Business & tailoring",
            listOf(
                s("What Is Tailoring?", "Tailoring is the deliberate adaptation of the project management approach, governance, and processes to make them more suitable for the specific project environment. It is driven by the 6 principles and guided by organisational values and culture."),
                s("What Is Tailoring?", "Tailoring is NOT \"do whatever you want.\" It requires justification, alignment with principles, and continuous assessment. The goal is to choose the MOST APPROPRIATE practices for the context — not the most convenient.", SectionKind.WARN),
                s("4-Step Tailoring Process (PMBOK 8)", tableHeaders = listOf("Step", "Action", "Key Considerations"), tableRows = listOf(listOf("1. Select Approach", "Choose predictive, adaptive, or hybrid as the starting point", "Deliverable uncertainty, team maturity, regulatory requirements, customer expectations, organisational culture"), listOf("2. Tailor for the Organisation", "Adapt to organisational constraints, PMO standards, governance requirements", "Compliance requirements, existing templates, tool availability, governance framework"), listOf("3. Tailor for the Project", "Further refine based on project-specific characteristics", "Project size, complexity, risk level, stakeholder needs, delivery cadence, team location"), listOf("4. Implement Ongoing Improvement", "Continuously assess and adjust throughout the project lifecycle", "Retrospectives, lessons learned, quality metrics, stakeholder feedback, issue patterns"))),
                s("Development Approach Selection Factors", tableHeaders = listOf("Factor", "Use Predictive When...", "Use Adaptive When..."), tableRows = listOf(listOf("Requirements", "Well-known, stable, detailed upfront", "Uncertain, evolving, hard to define upfront"), listOf("Change Rate", "Low — changes are costly and infrequent", "High — change is expected and valued"), listOf("Stakeholder Involvement", "Defined at key milestones", "Continuous, frequent collaboration"), listOf("Team", "Specialised roles; task-assigned", "Cross-functional; self-organising"), listOf("Delivery", "Single delivery at project end", "Frequent increments throughout"), listOf("Risk Tolerance", "Low — risks managed upfront", "Higher — risks managed iteratively"), listOf("Regulatory", "High compliance requirements", "More flexibility in approach"))),
                s("Scheduling Tailored by Lifecycle (PMBOK 8)", tableHeaders = listOf("Lifecycle", "Scheduling Approach"), tableRows = listOf(listOf("Predictive", "Detailed schedule baseline defined upfront. Changes managed through formal change control. Clear milestones, dependencies, and critical path."), listOf("Adaptive (Agile)", "Timeboxed sprints/iterations. Velocity-based forecasting. Backlog reprioritised each sprint. No fixed long-term schedule."), listOf("Hybrid", "High-level predictive milestones for stable deliverables; sprint-based scheduling for volatile components. CPM for stable work, Kanban for flowing work."))),
                s("Tailoring Diagnostics", "• Periodic retrospectives assess effectiveness of current approach and identify further tailoring needs\n• Teams without retrospectives: use issues, threats, quality metrics, and stakeholder feedback as diagnostic inputs\n• Key questions: Are processes adding value? Are they causing bottlenecks? Do they fit the team's actual way of working?\n• Documentation: Tailoring decisions should be documented and justified — not informal \"we just don't do that\""),
                s("What to Tailor — The Four Categories", tableHeaders = listOf("Category", "What Can Be Tailored", "Examples"), tableRows = listOf(listOf("Life Cycle & Development Approach", "Phases, cadence, predictive/adaptive/hybrid mix", "Add a pilot phase; use sprints for software but stage-gates for hardware"), listOf("Processes", "Add, remove, modify, blend, or align processes", "Skip formal quantitative risk analysis on a small project; add a security review process"), listOf("Engagement", "How people, empowerment, and integration are handled", "Co-located vs virtual; degree of team autonomy; PO vs traditional requirements"), listOf("Tools, Methods & Artifacts", "Templates, software, meetings, reports", "Kanban board instead of Gantt; user stories instead of requirements spec; weekly instead of daily reports"))),
                s("Tailoring Criteria — Project Uniqueness Factors", tableHeaders = listOf("Factor", "Low → Lightweight Tailoring", "High → Heavyweight Tailoring"), tableRows = listOf(listOf("Size", "Small team, short duration → minimal process", "Large team, long duration → formal processes and governance"), listOf("Criticality", "Low consequences of failure → agile experimentation", "Life-safety, financial, regulatory → rigorous verification, documentation"), listOf("Complexity", "Simple, well-understood → predictive plan", "Many interdependencies, emergent behaviour → iterative, adaptive"), listOf("Uncertainty", "Requirements clear → predictive", "Requirements unknown → adaptive; spikes; prototypes"), listOf("Team Experience", "Experienced, self-managing → delegate", "Junior, new to domain → more structure, coaching, checkpoints"), listOf("Team Distribution", "Co-located → informal, face-to-face", "Distributed → formal communication plan, async tools, overlap hours"), listOf("Stakeholder Environment", "Few, aligned → simple engagement", "Many, conflicting → formal stakeholder management, governance body"), listOf("Regulatory Requirements", "None → minimal documentation", "Heavily regulated → mandated documentation, audit trails, traceability"), listOf("Organisational Culture", "Innovative, trust-based → empowered teams", "Hierarchical, control-oriented → formal approvals, reporting"), listOf("Risk Threshold", "High tolerance → accept more risk, faster delivery", "Low tolerance → more contingency, more reviews, slower cadence"))),
                s("Tailoring Governance Structures", tableHeaders = listOf("Governance Element", "Predictive Tailoring", "Adaptive Tailoring", "Hybrid Tailoring"), tableRows = listOf(listOf("Decision Authority", "Steering committee; CCB", "Product Owner for product decisions; team for how", "Steering committee for strategic; PO for backlog"), listOf("Change Control", "Formal CCB; change log; impact analysis", "Backlog reprioritisation by PO", "Formal CCB for baseline; backlog for adaptive component"), listOf("Reviews / Gates", "Phase gates; milestone reviews", "Sprint reviews; retrospectives", "Phase gates at major milestones; sprint reviews within phases"), listOf("Reporting", "Status reports; EVM dashboards", "Information radiators; burndown; velocity", "EVM for predictive stream; burndown for agile stream"), listOf("Escalation", "Defined escalation path through hierarchy", "Scrum Master removes impediments; PO escalates product issues", "Both paths defined; clear ownership per component"), listOf("Risk Governance", "Risk register; formal reviews", "Risk-adjusted backlog; retrospective discussion", "Risk register + risk-adjusted backlog"))),
                s("Tailoring Artifacts", tableHeaders = listOf("Artifact", "Full Version (Large/Regulated)", "Tailored Version (Small/Agile)"), tableRows = listOf(listOf("Project Charter", "Multi-page document with all elements", "One-page project canvas / vision statement"), listOf("Requirements", "Requirements specification + RTM", "User stories with acceptance criteria"), listOf("Schedule", "Network diagram + Gantt + baseline", "Release plan + sprint backlog"), listOf("Risk Register", "Full register with quantitative analysis", "Risk board / risk-adjusted backlog"), listOf("Status Report", "Formal weekly report with EVM", "Information radiator + sprint review"), listOf("Change Log", "Formal CCB decisions", "Backlog history"), listOf("Lessons Learned", "Formal register + post-project review", "Retrospective action items"), listOf("Quality Plan", "Quality management plan + metrics", "Definition of Done"))),
                s("Common Tailoring Mistakes", tableHeaders = listOf("Mistake", "Why It Fails", "Correct Approach"), tableRows = listOf(listOf("Cherry-picking", "Taking only the \"easy\" parts of a method (e.g., Daily Scrum without retrospectives)", "Understand why each element exists before removing it"), listOf("Over-tailoring", "Removing so much that governance disappears", "Retain minimum viable governance — every project needs some"), listOf("Under-tailoring", "Applying full enterprise process to a 3-person project", "Scale process to project size and risk"), listOf("Tailoring by convenience", "Removing steps because they are hard, not because they are unnecessary", "Tailoring must be justified by project characteristics, not effort avoidance"), listOf("One-time tailoring", "Never revisiting the approach", "Retrospectives and diagnostics should trigger re-tailoring"), listOf("Undocumented tailoring", "\"We just don't do that\" — no rationale", "Document what was tailored and why in the PM plan"))),
                s("Tailoring Diagnostic — Signs You Need to Re-Tailor", tableHeaders = listOf("Symptom", "Likely Tailoring Issue", "Adjustment"), tableRows = listOf(listOf("Team spends more time on process than delivery", "Over-tailored (too heavy)", "Remove low-value ceremonies; simplify artifacts"), listOf("Repeated surprises; stakeholders blindsided", "Under-tailored governance", "Add checkpoints; formalise communication"), listOf("Defects found late", "Quality process too light", "Add reviews; strengthen Definition of Done"), listOf("Requirements churn; rework", "Wrong approach for uncertainty level", "Shift toward adaptive; add prototyping"), listOf("Decisions stall", "Unclear decision authority", "Define decision rights; add RACI"), listOf("Team disengaged", "Insufficient empowerment", "Increase autonomy; involve team in tailoring decisions"))),
                s("Worked example — 📖 Worked Example: Tailoring Decision — Small Project", "Context: A 3-person team at a startup needs to build an internal expense-tracking tool. Budget: ₹3 lakh. Duration: 6 weeks. Team knows the requirements well. No regulatory constraints. Sponsor is the CTO who sits 5 metres away.\n\nTailoring decisions:\n\nLife Cycle: Adaptive (Kanban). No sprints needed — work flows continuously. Daily standup: 10 minutes (informal).\n\nCharter: One-page project canvas — purpose, scope boundary, success criteria, budget. Signed in 30 minutes. NOT a 20-page document.\n\nChange Control: PO (the CTO) adds/removes backlog items as needed. No CCB. Any change affecting the 6-week deadline or ₹3L budget discussed face-to-face.\n\nRisk: A simple risk board (4 stickies) on the Kanban board. No formal risk register needed at this scale.\n\nQuality: Definition of Done: code reviewed by one peer, deployed to a test environment, tested by the user who requested the feature. No formal QA plan.\n\nStatus Reporting: The Kanban board IS the status report — the CTO walks past it daily. Weekly 15-minute sync. No written status reports.\n\nLessons Learned: 1-hour retro at project close. 1-page summary added to the company wiki.\n\nWhat was removed: Formal CCB, stakeholder register, communications management plan, risk register, quality management plan, formal status reports, phase gates.\n\nJustification: Small team, co-located, well-understood scope, no regulatory constraints, sponsor directly accessible. All removed elements would create overhead without value.", SectionKind.TIP),
                s("Worked example — 📖 Worked Example: Tailoring Decision — Large Regulated Project", "Context: A banking group is implementing a new SWIFT payment system across 12 countries. Budget: ₹180 crore. Duration: 36 months. RBI, SEBI, and 12 national regulators involved. 45 vendors. 200-person team across India, Singapore, UK.\n\nTailoring decisions:\n\nLife Cycle: Predictive (Waterfall) for infrastructure and regulatory components. Agile (Scrum, 2-week sprints) for configuration and testing components. Hybrid.\n\nCharter: Full 20-page document with legal sign-off, authority matrix, budget approval chain, regulatory references.\n\nChange Control: Full CCB with 8 members (Sponsor, PMO Head, Regulatory Liaison, CTO, Finance, 2 external members). Written change requests mandatory for all changes. 5-day turnaround for standard changes; emergency path for regulatory-driven changes.\n\nRisk: Full risk register (120+ risks identified). Quantitative risk analysis (Monte Carlo) for schedule and cost. Risk review every 2 weeks with steering committee.\n\nQuality: Full quality management plan. ISO 20022 compliance verification. External audit at Phase 2 gate. Regulatory acceptance criteria formally documented.\n\nStatus Reporting: Weekly written status to PMO. Monthly steering committee dashboard. Quarterly regulatory report. Country-specific reports for each of 12 regulators.\n\nTailoring justification: 36 months, ₹180 crore, 12 regulators, 45 vendors, 200 people. Full governance is justified — removing ANY of these elements creates regulatory, financial, or operational risk at scale.\n\nThe lesson: The same PM framework applied to both projects — but the CALIBRATION is completely different. Tailoring is not about cutting corners. It is about right-sizing governance to the risk and complexity of the specific project.", SectionKind.TIP),
                s("Worked example — 📖 Worked Example: Tailoring Diagnostic — When to Re-Tailor", "Project: A digital KYC platform (hybrid approach, 9 months in, 3 months to go).\n\nSymptoms observed in the last 3 sprints:\n\n• Sprint reviews consistently show 60% completion (never near the goal)\n\n• The same blockers appear in every retrospective and are never resolved\n\n• Business stakeholders stopped attending sprint reviews (\"nothing useful ever ships\")\n\n• The team spends 30% of sprint time in governance meetings\n\nDiagnostic questions (PMBOK 8):\n\n1. Are processes adding overhead without value? → Yes: 30% in governance meetings is excessive\n\n2. Are sprint goals realistic? → No: consistently 60% hit rate means poor estimation or scope instability\n\n3. Are impediments being removed? → No: same blockers appearing for 3 sprints\n\n4. Is the development approach right? → Partially: hybrid works, but the predictive governance overhead is too heavy\n\nRe-tailoring decisions:\n\n• Reduce governance meetings from weekly to bi-weekly; move minor decisions to async Slack approvals\n\n• Add a \"blocker escalation\" protocol: any blocker unresolved for >48 hours is automatically escalated to PM\n\n• Sprint review: add a \"mini-demo\" of in-progress items (not just completed) to maintain stakeholder visibility\n\n• Estimation: conduct a one-sprint calibration exercise — re-estimate using yesterday's weather method\n\nResult: Sprint 10 completion rate: 80%. Governance meeting time: 12% of sprint. Stakeholders re-engaged. Two blockers resolved within 24 hours of the new protocol.", SectionKind.TIP),
            )
        ),
        Chapter(
            "agile",
            "🔄 Agile, Scrum & Hybrid",
            "Agile Manifesto — 4 Values",
            "Agile & Scrum",
            listOf(
                s("Agile Manifesto — 4 Values", tableHeaders = listOf("We Value... (Left — Higher Priority)", "Over... (Right — Still Has Value)"), tableRows = listOf(listOf("Individuals and interactions", "Processes and tools"), listOf("Working software", "Comprehensive documentation"), listOf("Customer collaboration", "Contract negotiation"), listOf("Responding to change", "Following a plan"))),
                s("Agile Manifesto — 4 Values", "Items on the RIGHT still have value — Agile does NOT eliminate them. The values express relative PRIORITY. A team that produces no documentation and ignores all processes is not agile — it is just disorganised.", SectionKind.WARN),
                s("12 Agile Principles — Grouped by Theme", tableHeaders = listOf("Theme", "Key Principles"), tableRows = listOf(listOf("Customer Value", "Highest priority is early and continuous delivery of valuable software. Welcome changing requirements — even late in development."), listOf("Delivery", "Deliver working software frequently — from weeks to months. Working software is the primary measure of progress."), listOf("Collaboration", "Business people and developers work together daily. Face-to-face conversation is the most efficient method."), listOf("Motivation", "Build projects around motivated individuals. Give them the environment and support they need and trust them to get the job done."), listOf("Technical Excellence", "Continuous attention to technical excellence and good design enhances agility. Simplicity — maximise work NOT done."), listOf("Reflection", "At regular intervals, team reflects on how to become more effective — then adjusts accordingly (retrospectives)."))),
                s("Scrum: 3-5-3 Rule", "3 Roles\n • Product Owner: Owns and PRIORITISES the Product Backlog; maximises product value; single point of accountability; only ONE person (not a committee); accepts/rejects sprint output\n• Scrum Master: SERVANT LEADER; removes impediments; facilitates ceremonies; coaches team on Scrum; shields team from interruptions; helps PO with backlog refinement — NOT a traditional PM\n• Developers: Cross-functional; self-organising; 3–9 members; designs, builds, and tests the increment; creates their own Sprint Backlog\n\n 3 Artifacts\n • Product Backlog: Ordered list of all known work for the product; owned by PO; never complete; evolves throughout the product's life\n• Sprint Backlog: Selected Product Backlog items for this sprint + plan to deliver them; owned by Developers; visible to all\n• Increment: Sum of ALL completed backlog items to date; MUST meet Definition of Done; must be usable; potentially shippable after every sprint"),
                s("5 Events (Ceremonies)", tableHeaders = listOf("Event", "Timebox (4-week sprint)", "Purpose"), tableRows = listOf(listOf("Sprint", "1–4 weeks", "Fixed iteration delivering potentially shippable increment"), listOf("Sprint Planning", "≤8 hours", "Select backlog items; define Sprint Goal; create Sprint Backlog"), listOf("Daily Scrum", "15 minutes", "Inspect progress toward Sprint Goal; plan next 24 hours; 3 questions: Yesterday? Today? Impediments?"), listOf("Sprint Review", "≤4 hours", "Demo increment to stakeholders; gather feedback; update Product Backlog"), listOf("Sprint Retrospective", "≤3 hours", "Inspect process; identify improvements; create improvement plan — team only"))),
                s("Sprint Review vs. Sprint Retrospective — Know the Difference", "Sprint Review\n • Focus: Improve the PRODUCT (what was built)\n• Attendees: Scrum Team + Stakeholders, customers, management\n• Output: Updated Product Backlog; next steps; stakeholder feedback\n• Order: Second-to-last event of the Sprint\n• Duration: ≤4 hours for a 4-week Sprint"),
                s("Sprint Retrospective", "• Focus: Improve the PROCESS and TEAM (how it was built)\n• Attendees: Scrum Team ONLY — no external stakeholders\n• Output: Actionable improvements committed for next sprint\n• Order: LAST event of the Sprint (after Review, before next Planning)\n• Duration: ≤3 hours for a 4-week Sprint"),
                s("Sprint Retrospective", "Sprint Review = improve the PRODUCT. Sprint Retrospective = improve the PROCESS. Retro always comes AFTER Review and BEFORE the next Sprint Planning. This order is tested.", SectionKind.KEY),
                s("Scrum Rules — Non-Negotiable", "• Sprint duration is FIXED — never extended or shortened once started\n• Sprint Goal should NOT change during a Sprint — protects team focus\n• ONLY the Product Owner can cancel a Sprint, and ONLY if the Sprint Goal becomes obsolete\n• Scrum Master does NOT assign tasks, manage resources, or act as project manager\n• The TEAM creates their own estimates — PM/SM never estimates FOR them\n• Definition of Done (DoD): owned by Developers; defines \"complete\" for any increment; if DoD not met, item is NOT done\n• Backlog Refinement: ongoing; recommended ≤10% of Sprint capacity; not a formal Scrum event"),
                s("Agile Metrics", tableHeaders = listOf("Metric", "Definition", "Used For"), tableRows = listOf(listOf("Velocity", "Average story points completed per Sprint over recent sprints", "Forecast future sprint capacity and release dates"), listOf("Burndown Chart", "Remaining work (points or tasks) over time — slopes down toward zero", "Daily sprint progress; predicts if Sprint Goal is at risk"), listOf("Burnup Chart", "Completed work AND total scope over time — shows scope changes", "Release tracking; reveals scope additions clearly"), listOf("Lead Time", "Time from CUSTOMER REQUEST to delivery (full end-to-end flow time)", "Measures overall system responsiveness to customer needs"), listOf("Cycle Time", "Time from when work STARTS to when it is delivered", "Measures team's internal throughput efficiency; Cycle Time = WIP / Throughput"), listOf("WIP (Work in Progress)", "Number of items actively being worked on at any time", "WIP limits prevent overloading; expose and resolve bottlenecks"), listOf("Throughput", "Number of items (stories/features) completed per unit of time", "Team productivity measure; used for delivery forecasting"))),
                s("Agile Work Hierarchy", tableHeaders = listOf("Level", "Description", "Example"), tableRows = listOf(listOf("Theme", "High-level strategic focus guiding big-picture work toward business goals — strategic level", "Increase ecommerce website traffic by 30%"), listOf("Epic", "Large body of work spanning multiple releases; a significant feature or function", "Wishlist feature set for the ecommerce site"), listOf("User Story", "\"As a [type of user], I want [feature] so that [benefit/reason]\" — functional requirement in user language", "As a customer, I want to save items to my wishlist so I can buy them later"), listOf("Task", "Individual technical activity or step required to complete a user story", "Add \"Save to Wishlist\" button on each product page; create wishlist database table"))),
                s("Kanban Principles", "• Visualise the workflow — make all work visible on a Kanban board\n• WIP Limits — cap items in each stage; prevent overloading; force resolution of bottlenecks\n• Manage flow — focus on smooth, fast, predictable delivery\n• Make process policies explicit — everyone knows the rules of the workflow\n• Bottleneck: When work piles up in one column, stop pulling new work — focus the whole team on clearing the bottleneck. Work from the RIGHT-MOST full column first.\n• Continuous flow — unlike Scrum, there are no timeboxed sprints; work flows continuously"),
                s("Hybrid Approaches — When and How", "• Project has BOTH stable components (use predictive) and volatile/uncertain components (use adaptive)\n• Organisation is TRANSITIONING to agile but not fully there yet — keep some predictive guardrails\n• Regulatory requirements mandate specific deliverables (predictive) while development is agile\n• Example: Predictive for hardware, infrastructure, and compliance documentation; agile for software development; Kanban for support and maintenance\n• Key: Tailoring should be DELIBERATE and JUSTIFIED — not random mixing of methods"),
                s("Other Agile Frameworks — Beyond Scrum", tableHeaders = listOf("Framework", "Key Features", "When Used"), tableRows = listOf(listOf("Kanban", "Visualise flow; WIP limits; continuous delivery; no timeboxes", "Support/maintenance; operations; unpredictable work arrival"), listOf("XP (Extreme Programming)", "TDD, pair programming, CI, refactoring, simple design, collective ownership", "Software engineering excellence; high technical rigour"), listOf("Lean", "Eliminate waste; amplify learning; deliver fast; empower team; build integrity; see the whole", "Manufacturing-inspired; process optimisation"), listOf("Crystal", "Family of methods scaled by team size and criticality (Clear, Yellow, Orange, Red)", "Choosing method rigour based on project size/risk"), listOf("FDD (Feature-Driven Development)", "Feature lists; design by feature; build by feature; 2-week iterations", "Large teams; feature-centric products"), listOf("DSDM", "MoSCoW prioritisation; timeboxing; fixed time/cost, variable scope", "Business-focused agile; regulated environments"), listOf("Scrumban", "Scrum roles/events + Kanban flow and WIP limits", "Teams transitioning from Scrum to Kanban"))),
                s("Scaling Agile", tableHeaders = listOf("Framework", "Key Elements", "Scale"), tableRows = listOf(listOf("SAFe (Scaled Agile Framework)", "Agile Release Trains (ART); PI Planning (quarterly); Portfolio/Program/Team levels; WSJF prioritisation", "Large enterprises; 50–125+ people per ART"), listOf("LeSS (Large-Scale Scrum)", "One Product Backlog; one PO; multiple teams; shared Sprint Review", "2–8 teams on one product"), listOf("Scrum of Scrums", "Representatives from each Scrum team meet to coordinate dependencies", "Multiple Scrum teams; lightweight coordination"), listOf("Nexus", "Scrum.org framework; Nexus Integration Team; integrated increment", "3–9 Scrum teams on one product"), listOf("Disciplined Agile (PMI)", "Toolkit approach; \"choose your way of working\"; hybrid-friendly", "PMI's own framework; flexible"))),
                s("Lean Principles and Waste (TIMWOODS)", tableHeaders = listOf("Waste", "Description", "Software Example"), tableRows = listOf(listOf("Transport", "Unnecessary movement of materials/information", "Handoffs between teams"), listOf("Inventory", "Excess work in progress or unused features", "Half-built features; large backlogs"), listOf("Motion", "Unnecessary movement of people", "Switching between tools/systems"), listOf("Waiting", "Idle time waiting for something", "Waiting for approvals; build times"), listOf("Overproduction", "Making more than needed", "Building features nobody asked for (gold plating)"), listOf("Over-processing", "Doing more work than required", "Excessive documentation; unnecessary meetings"), listOf("Defects", "Rework due to errors", "Bugs; failed tests; rejected deliverables"), listOf("Skills (unused)", "Not using people's full capabilities", "Developers not involved in design decisions"))),
                s("Agile Contracts and Governance", "• Servant leadership applies to governance too — governance serves the team, not vice versa\n• Lightweight governance: Sprint reviews act as phase gates; retrospectives as process audits\n• Agile in regulated environments: Documentation still required — but produced incrementally alongside the increment\n• Agile PMO: Coaches teams; provides templates; measures outcomes not compliance\n• Value stream mapping: Visualise the flow of value from concept to customer; identify waste"),
                s("Agile Metrics — Advanced", tableHeaders = listOf("Metric", "Definition", "Healthy Trend"), tableRows = listOf(listOf("Cumulative Flow Diagram (CFD)", "Stacked area chart showing items in each workflow state over time", "Bands stay roughly parallel; widening band = bottleneck"), listOf("Escaped Defects", "Defects found by customers after release", "Decreasing over time"), listOf("Sprint Goal Success Rate", "% of sprints where the Sprint Goal was met", "High and stable (80%+)"), listOf("Team Happiness / Morale", "Self-reported team satisfaction", "Stable or improving — leading indicator of productivity"), listOf("Cycle Time Distribution", "Histogram of cycle times", "Narrow distribution = predictable delivery"), listOf("Net Promoter Score (NPS)", "Would customers recommend the product?", "Increasing"))),
                s("Hybrid Patterns — Common Combinations", tableHeaders = listOf("Pattern", "Description", "Example"), tableRows = listOf(listOf("Predictive shell, agile core", "Overall project managed predictively; development done in sprints", "Government IT project with fixed milestones but agile software delivery"), listOf("Agile shell, predictive components", "Product managed agilely; some components predictive", "Software product with hardware component built predictively"), listOf("Sequential hybrid", "Phases alternate — predictive planning, agile build, predictive deployment", "Construction with BIM modelling done agilely"), listOf("Parallel hybrid", "Predictive and agile workstreams run simultaneously", "ERP implementation: infrastructure predictive, config agile"))),
                s("Worked example — Scrum in Practice — A Full Sprint Walk-Through", "Project: Building a UPI payments feature for a neobank app\n\nTeam: 1 Product Owner (Priya), 1 Scrum Master (Rahul), 5 Developers\n\nSprint: 2 weeks | Velocity: ~35 story points\n\nDAY 0 — SPRINT PLANNING (≤4 hours for 2-week sprint):\n\nProduct Backlog top items (already refined):\n\n• [8pts] As a user, I want to link my bank account via UPI ID\n\n• [5pts] As a user, I want to initiate a payment with PIN confirmation\n\n• [5pts] As a user, I want to see my last 10 transactions\n\n• [3pts] As a user, I want to receive push notification on payment success\n\n• [8pts] As a user, I want to set a daily transaction limit\n\n• [5pts] Performance: payment API response DAYS 1–10 — EXECUTING (with Daily Scrum):\n\nDaily Scrum (15 minutes, same time each day):\n\nDev 1: \"Yesterday: completed UPI ID validation logic. Today: starting bank lookup API integration. Blockers: NPCI sandbox credentials not received yet.\"\n\nScrum Master Rahul: \"I'll escalate the NPCI credentials to Priya — she has the bank contact.\" [IMPEDIMENT REMOVED by end of day]\n\nDay 6 — Mid-sprint concern:\n\nThe transaction limit feature is proving more complex than estimated (security review needed). Rahul alerts Priya. Priya decides: remove transaction limit from this sprint, add push notifications instead (smaller scope). Sprint Backlog adjusted — Sprint GOAL unchanged.\n\nDAY 10 — SPRINT REVIEW (≤2 hours for 2-week sprint):\n\nAttendees: Scrum Team + Product Manager, 2 business stakeholders\n\nDemo: Priya demos account linking and payment flow on a staging device\n\nStakeholder feedback: \"The PIN screen is confusing — can we add a visual keyboard?\" → Added to Product Backlog. \"Great work on the speed.\"\n\nProduct Backlog updated with new items\n\nDAY 10 — SPRINT RETROSPECTIVE (≤1.5 hours for 2-week sprint):\n\nAttendees: Scrum Team ONLY (no stakeholders)\n\nWent well: \"Good collaboration on the NPCI issue; resolved in 4 hours\"\n\nImprovement: \"We underestimated regulatory complexity of the transaction limit feature — next time, regulatory stories need a 'complexity spike' before sizing\"\n\nAction: \"Before next sprint, do a 2-point spike on daily limit regulatory requirement\" — assigned to Dev 2 by Day 2 next sprint\n\nIncrement produced: Account linking + UPI payment + last 10 transactions + push notifications. All meet DoD. Potentially shippable.", SectionKind.TIP),
                s("Worked example — Kanban Board — Reading and Acting on It", "Team: API Platform support team (continuous flow — no sprints)\n\nWIP limits: Backlog(∞) → Analysis(3) → Development(4) → Code Review(2) → Testing(3) → Done\n\nCurrent board state:\n\nBacklog: 12 items\n\nAnalysis: 3 items ✅ (at limit)\n\nDevelopment: 4 items ✅ (at limit)\n\nCode Review: 6 items ❌ (limit is 2 — 3× over limit)\n\nTesting: 1 item ✅\n\nDone: 8 items today\n\nWhat the board is telling you:\n\nCode Review is a BOTTLENECK. Work is piling up waiting for review. Development keeps pushing code, but it cannot move forward. The whole system is backing up.\n\nWhat to do — Kanban response:\n\n1. STOP pulling new items into Development (even if WIP allows it)\n\n2. SWARM on Code Review — developers who are waiting for review help with reviews\n\n3. Ask: WHY is code review slow? (Reviewer unavailable? Review criteria unclear? Items too large?)\n\n4. In this case: the two assigned reviewers are both blocked by a production incident. Solution: PM escalates to free up one reviewer; another developer gets temporarily upskilled for review\n\nLead Time analysis: Items are now averaging 8 days from start to done. The Code Review bottleneck is adding 3 days of wait time.\n\nProcess Cycle Efficiency = Actual work time / Total lead time = 5 days / 8 days = 62.5% — good, but could be better.\n\nKey Kanban insight: The bottleneck is ALWAYS the right place to focus. More work upstream of a bottleneck = more waste. Always work from the RIGHT side of the board first.", SectionKind.TIP),
                s("Worked example — User Story — Writing and Breaking Down", "Epic: International Money Transfer Feature\n\nUser Story (well-written):\n\n\"As an NRI customer, I want to transfer money to an Indian bank account from my UK account so that I can support my family without visiting a bank branch.\"\n\nAcceptance Criteria (using Given-When-Then):\n\n• Given I am logged in and my UK account is verified,\n\n  When I initiate a transfer of £100 to an IFSC-linked account,\n\n  Then the transfer is processed within 2 business days and I receive a confirmation email with reference number.\n\n• Given exchange rates fluctuate,\n\n  When I initiate a transfer,\n\n  Then the system shows me the live exchange rate and locks it for 30 minutes.\n\n• Given a transfer fails due to incorrect IFSC,\n\n  When the system detects the error,\n\n  Then I receive an error message within 5 seconds with the specific reason and a correction guide.\n\nINVEST criteria check:\n\n✅ Independent — can be tested and delivered without other stories\n\n✅ Negotiable — the 30-minute rate lock is a business decision, can be changed\n\n✅ Valuable — directly solves an NRI customer need\n\n✅ Estimable — team can size it (likely 13 story points)\n\n✅ Small — fits within one sprint\n\n✅ Testable — acceptance criteria are clear and testable\n\nDefinition of Done for this story:\n\nCode reviewed ✅ | Unit tests written (>85% coverage) ✅ | Integration test with UK banking API passed ✅ | Compliance team signed off ✅ | Deployed to staging ✅ | PO accepted in sprint review ✅", SectionKind.TIP),
            )
        ),
